/*
 * qbrt.h - LinBASIC runtime interface used by code generated by lbc.
 *
 * This header deliberately includes no system headers so that generated
 * programs can be compiled by the bundled Tiny C Compiler without any
 * C library development files installed on the user's machine.
 *
 * Copyright (C) 2026 Demosthenes Koptsis. GPL-3.0-or-later.
 */
