/* ---- strings ---------------------------------------------------------- */
/* A qbs is a string value.  flags: 1 = owned heap buffer (variable),
   2 = FIELD-mapped buffer (owned by a file record buffer). */
typedef struct qbs { char *p; qb_i32 len; qb_i32 flags; } qbs;

#define QB_NA (-2147483647 - 1)          /* "argument omitted" for ints  */
#define QB_NAD (-1.0e300)                /* "argument omitted" for reals */

