/* ---- arrays ----------------------------------------------------------- */
typedef struct qbarr {
    char *data;
    qb_i32 nd;        /* number of dimensions (0 = not dimensioned) */
    qb_i32 esz;       /* element size in bytes                      */
    qb_i32 kind;      /* 0 = plain memory, 1 = qbs elements          */
    qb_i32 isdyn;     /* 1 = $DYNAMIC (ERASE frees)                  */
    qb_i32 n;         /* total number of elements                    */
    qb_i32 lb[8], ub[8], mul[8];
} qbarr;

void qb_adim(qbarr *a, qb_i32 esz, qb_i32 kind, qb_i32 isdyn, qb_i32 nd, ...);  /* lb,ub pairs */
void qb_aredim(qbarr *a, qb_i32 esz, qb_i32 kind, qb_i32 nd, ...);
void qb_aerase(qbarr *a);
void qb_afree(qbarr *a);
qb_i32 qb_aoff(qbarr *a, qb_i32 nd, ...);
qb_i32 qb_lbound(qbarr *a, qb_i32 dim);
qb_i32 qb_ubound(qbarr *a, qb_i32 dim);
void qb_acopy(qbarr *dst, qbarr *src);   /* used for COMMON/CHAIN */

static inline qb_i32 qb_aoff1(qbarr *a, qb_i32 i) {
    extern qb_i32 qb_aoff_err(qbarr *a);
    if (a->nd != 1 || i < a->lb[0] || i > a->ub[0]) return qb_aoff_err(a);
    return i - a->lb[0];
}
static inline qb_i32 qb_aoff2(qbarr *a, qb_i32 i, qb_i32 j) {
    extern qb_i32 qb_aoff_err(qbarr *a);
    if (a->nd != 2 || i < a->lb[0] || i > a->ub[0] || j < a->lb[1] || j > a->ub[1]) return qb_aoff_err(a);
    return (i - a->lb[0]) + (j - a->lb[1]) * a->mul[1];
}
#define QB_AE(arr, T, off) (((T *)(arr)->data)[off])

