static inline qb_i16 qb_ci16(qb_i32 v) { if (v < -32768 || v > 32767) { qb_error(6); return 0; } return (qb_i16)v; }
static inline qb_i32 qb_ci32(qb_i64 v) { if (v < -2147483647LL - 1 || v > 2147483647LL) { qb_error(6); return 0; } return (qb_i32)v; }
